#!/usr/bin/env bash
# Runs the Go model with the given config (default: out/default.yaml, as
# generated by scripts/params_to_config.py). Output goes to the given
# directory (default: out/go/).
set -euo pipefail
cd "$(dirname "$0")/.."
config="${1:-out/default.yaml}"
out_dir="${2:-out/go}"
go build -C ../pwn -o "$PWD/pwn" .
./pwn "$config" -o "$out_dir"
